def transform_v4(horiz_row, vert_col, grid_h, grid_w):
    """Fill cells that are 'edge-biased' within their quadrant"""
    result = [[0]*grid_w for _ in range(grid_h)]

    # Draw cross
    for c in range(grid_w):
        result[horiz_row][c] = 3
    for r in range(grid_h):
        result[r][vert_col] = 3

    for r in range(grid_h):
        for c in range(grid_w):
            if r != horiz_row and c != vert_col:
                # Calculate distances
                dist_to_top = r
                dist_to_bottom = grid_h - 1 - r
                dist_to_left = c
                dist_to_right = grid_w - 1 - c

                min_edge = min(dist_to_top, dist_to_bottom, dist_to_left, dist_to_right)

                # Determine which "direction" we're closest to
                if dist_to_top == min_edge:
                    direction = 'top'
                elif dist_to_bottom == min_edge:
                    direction = 'bottom'
                elif dist_to_left == min_edge:
                    direction = 'left'
                else:
                    direction = 'right'

                # Fill based on direction relative to cross position
                # If we're on the "far side" of cross from the nearest edge → don't fill
                if direction == 'top':
                    if r < horiz_row:
                        result[r][c] = 4  # Fill far side
                elif direction == 'bottom':
                    if r > horiz_row:
                        result[r][c] = 4
                elif direction == 'left':
                    if c < vert_col:
                        result[r][c] = 4
                elif direction == 'right':
                    if c > vert_col:
                        result[r][c] = 4

    return result

